#include <iostream>
#include <fstream>
using namespace std;
int main() {
    ifstream in("src.bin", ios::in | ios::binary | ios::ate);
    if (!in.is_open()) return 1;
    streampos size = in.tellg();          // ate: opened at the end, so tellg = file size
    char* memblock = new char[size];
    in.seekg(0, ios::beg);                // rewind to the beginning
    in.read(memblock, size);
    in.close();

    ofstream out("des.bin", ios::out | ios::binary);
    out.write(memblock, size);
    out.close();
    delete[] memblock;
    return 0;
}

