bool operator>(const inf_int& x, const inf_int& y) {
    if (x.thesign != y.thesign) return x.thesign;     // positive > negative
    bool absGreater;
    if (x.length != y.length) absGreater = x.length > y.length;
    else {
        int i = x.length - 1;                          // compare from the most significant digit
        while (i >= 0 && x.digits[i] == y.digits[i]) i--;
        if (i < 0) return false;                       // equal
        absGreater = x.digits[i] > y.digits[i];
    }
    return x.thesign ? absGreater : !absGreater;       // if negative, the larger absolute value is smaller
}
inf_int::inf_int(const inf_int& x) {
    length = x.length;
    thesign = x.thesign;
    digits = new char[length + 1];   // deep copy
    strcpy(digits, x.digits);
}
inf_int::inf_int(int n) {
    char buf[100]; int i = 0;
    long long m = n;               // guards against INT_MIN
    thesign = (m >= 0);
    if (m < 0) m = -m;
    do { buf[i++] = '0' + m % 10; m /= 10; } while (m > 0);   // stored in reverse order
    buf[i] = '\0';
    length = i;
    digits = new char[length + 1];
    strcpy(digits, buf);
}

