inf_int::inf_int(const char* str) {
    thesign = true;
    if (str[0] == '-') { thesign = false; str++; }
    length = strlen(str);
    digits = new char[length + 1];
    for (unsigned int i = 0; i < length; i++)
        digits[i] = str[length - 1 - i];   // stored in reverse order
    digits[length] = '\0';
}

